package com.jijing.fund.infrastructure.knowledge;
import com.fasterxml.jackson.databind.ObjectMapper;import java.time.Duration;import okhttp3.mockwebserver.*;import org.junit.jupiter.api.*;import static org.assertj.core.api.Assertions.assertThat;
class ElasticsearchIndexGovernanceGatewayTest {
 private MockWebServer server;@BeforeEach void start()throws Exception{server=new MockWebServer();server.start();}@AfterEach void stop()throws Exception{server.shutdown();}
 @Test void rebuildValidatesCountsAndAtomicallySwitchesAliases()throws Exception{server.enqueue(response(404,""));server.enqueue(response(200,""));server.enqueue(response(200,"{\"fund_docs\":{\"mappings\":{\"properties\":{\"embedding\":{\"type\":\"dense_vector\",\"dims\":2}}}}}"));server.enqueue(response(200,"{\"acknowledged\":true}"));server.enqueue(response(200,"{\"count\":3}"));server.enqueue(response(200,"{\"version_conflicts\":0,\"failures\":[]}"));server.enqueue(response(200,"{\"count\":3}"));server.enqueue(response(200,""));server.enqueue(response(200,""));server.enqueue(response(200,"{\"acknowledged\":true}"));var gateway=new ElasticsearchIndexGovernanceGateway(server.url("/").toString(),"fund_docs",new ObjectMapper(),null,null,null,Duration.ofSeconds(1),Duration.ofSeconds(2));var prepared=gateway.rebuild("00000000-0000-0000-0000-000000000001");assertThat(prepared.expectedCount()).isEqualTo(3);assertThat(prepared.indexedCount()).isEqualTo(3);assertThat(prepared.validation()).containsEntry("embeddingDimensions",2);gateway.activate(prepared.readAlias(),prepared.writeAlias(),prepared.previousIndex(),prepared.targetIndex());RecordedRequest last=null;for(int i=0;i<10;i++)last=server.takeRequest();assertThat(last.getPath()).isEqualTo("/_aliases");assertThat(last.getBody().readUtf8()).contains("fund_docs_read",prepared.targetIndex());}
 private MockResponse response(int code,String body){return new MockResponse().setResponseCode(code).setBody(body);}
}
